cat > /tmp/fuzz.c <<'EOF'
#include "collector.h"
#include "epic_clean.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

static int emitted;
static int emit_cb(void *user,int rank,const uint8_t *frame,size_t len)
{
    (void)user;(void)rank;(void)frame;(void)len;
    emitted++;
    return 1;
}
static uint32_t rnd_state=12345;
static uint32_t rnd(void){ rnd_state=rnd_state*1103515245u+12345u; return rnd_state>>8; }

int main(void)
{
    static uint8_t frame[8192];
    static uint8_t body[4096];
    for(int trial=0;trial<120;trial++){
        int prim=(int)(rnd()%6), mode=2+(int)(rnd()%2), root=(int)(rnd()%4);
        uint32_t D=1+rnd()%64, K=1+rnd()%32, N=1+rnd()%16, start=rnd()%(1u<<24);
        collector_t *c=collector_open(prim,mode,root,K,D,N,start,emit_cb,NULL);
        if(!c)return 1;
        for(int i=0;i<300;i++){
            int kind=(int)(rnd()%4);
            if(kind==0||kind==1){
                int rank=(int)(rnd()%4);
                uint8_t hostmac[6]={2,0,0,0,0,(uint8_t)(rank+1)};
                uint8_t swmac[6]={2,1,0,0,0,(uint8_t)(rank+1)};
                uint32_t hostip=htonl(0x0a000001u+(uint32_t)rank);
                uint32_t swip=htonl(0x0a000065u+(uint32_t)rank);
                size_t plen=4u*D;
                for(size_t j=0;j<plen;j++)body[j]=(uint8_t)rnd();
                uint32_t psn=(start+rnd()%K)&0xffffffu;
                size_t n=epic_build_roce_data_raw(frame,sizeof(frame),swmac,hostmac,swip,hostip,
                                                  4791,4791,0x200u+(uint32_t)rank,psn,body,plen);
                if(!n)return 3;
                if(rnd()%4==0)frame[rnd()%n]^=(uint8_t)(1u<<(rnd()%8));
                collector_ingress(c,rank,frame,n);
            } else if(kind==2){
                int rank=(int)(rnd()%4);
                uint8_t hostmac[6]={2,0,0,0,0,(uint8_t)(rank+1)};
                uint8_t swmac[6]={2,1,0,0,0,(uint8_t)(rank+1)};
                uint32_t hostip=htonl(0x0a000001u+(uint32_t)rank);
                uint32_t swip=htonl(0x0a000065u+(uint32_t)rank);
                uint32_t psn=(start+rnd()%(3*K+1))&0xffffffu;
                size_t n=epic_build_roce_ack(frame,sizeof(frame),swmac,hostmac,swip,hostip,
                                              4791,4791,0x200u+(uint32_t)rank,psn);
                if(!n)return 4;
                collector_ingress(c,rank,frame,n);
            } else {
                size_t len=rnd()%300;
                for(size_t j=0;j<len;j++)frame[j]=(uint8_t)rnd();
                collector_ingress(c,(int)(rnd()%4),frame,len);
            }
            if(rnd()%8==0)collector_flush(c);
            if(rnd()%8==0)collector_retry(c,(int)(rnd()%4));
        }
        uint64_t st[32];collector_state(c,st);uint64_t h=collector_digest(c);
        if(st[30]||st[31]){fprintf(stderr,"counter %llu\n",(unsigned long long)st[30]);return 2;}
        (void)h;
        collector_close(c);
    }
    printf("fuzz done, emitted=%d\n",emitted);
    return 0;
}
EOF
cd /tmp && gcc -std=c11 -O2 -g -D_FORTIFY_SOURCE=2 -I/workspace/project/include /tmp/fuzz.c /workspace/project/src/roce_packet.c /workspace/project/src/star4_switch.c -o /tmp/fuzz_plain 2>&1|tail -2; MALLOC_CHECK_=3 MALLOC_PERTURB_=165 /tmp/fuzz_plain; echo "rc=$?"
